\cite{Kal}
		Let $\mathcal{A}$ be a unital $ C^{\ast}- $ algebra and $ \mathcal{H} $ be a left $ \mathcal{A}-$ module, such that the linear structures of $ \mathcal{A} $ and $ \mathcal{H} $ are compatible. $ \mathcal{H} $ is a pre-Hilbert $ \mathcal{A} $ module if $ \mathcal{H} $ is equipped with an $ \mathcal{A}- $valued inner product $ \langle \cdot, \cdot\rangle_{\mathcal{A}}  : \mathcal{H} \times \mathcal{H}\rightarrow \mathcal{A}$ such that is sesquilinear, positive definite and respects the module action. In the other words,
		\begin{itemize}
			\item [1]- $\langle x, x\rangle_{\mathcal{A}}  \geq 0$,    $ \forall x\in \mathcal{H}$ and $\langle x, x\rangle_{\mathcal{A}}  = 0$ if and only if $ x=0 $.
			\item [2]- $\langle ax+y, z\rangle_{\mathcal{A}}  =a\langle x,z\rangle_{\mathcal{A}} +\langle y,z\rangle_{\mathcal{A}}  $ for all $ a\in \mathcal{A} $ and $ x,y,z \in \mathcal{H} $
		\item[3]- $ \langle x,y \rangle_{\mathcal{A}}  =  \langle y,x \rangle_{\mathcal{A}} ^{\ast}$ for all $ x,y \in\mathcal{H} $.
		\end{itemize}
	For $ x\in\mathcal{H} $, we define $\Vert x\Vert = \Vert \langle x,x \rangle_{\mathcal{A}}  \Vert^{\frac{1}{2}}$. If $ \mathcal{H} $ is complete with $ \Vert .\Vert $, it is called a Hilbert $ \mathcal{A}- $module or a Hilbert $ C^{\ast} -$module over $ \mathcal{A} $. For every $a$ in $ C^{\ast}- $algebra $ \mathcal{A} $, we have  $ \vert a \vert = (a^{\ast}a)^{\frac{1}{2}} $ and the $ \mathcal{A}- $valued norm on $ \mathcal{H} $ is defined by $ \vert x\vert= \langle x,x\rangle_{\mathcal{A}} ^{\frac{1}{2}} $ for $ x\in\mathcal{H} $.

\cite{Ara}\label{L22}
Let $\mathcal{H}$ and $\mathcal{K}$ two Hilbert $\mathcal{A}$-modules and $\mathcal{T} \in \operatorname{End}^*(\mathcal{H}, \mathcal{K})$. Then the following statements are equivalent
\begin{enumerate}
\item $\mathcal{T}$ is surjective.
\item  $\mathcal{T}^*$ is bounded below with respect to norm, i.e., there is $m>0$ such that $m\|x\| \leq\left\|\mathcal{T}^* x\right\|$ for all $x \in \mathcal{K}$.
\item $\mathcal{T}^*$ is bounded below with respect to the inner product, i.e., there is $m^{\prime}>0$ such that $m^{\prime}\langle x, x\rangle \leq\left\langle \mathcal{T}^* x, \mathcal{T}^* f\right\rangle$ for all $x \in\mathcal{K}$.
\end{enumerate}

\cite{Kal} A collection $ \{x_{\zeta}\}_{\zeta\in \Theta}\subset \mathcal{H} $ is called a frame for $ \mathcal{H} $. If there exist two positive constants $ A $ and $ B $ such that for all $ x\in \mathcal{H} $, 
	\begin{equation}\label{eq1}
		A\langle x,x\rangle_{\mathcal{A}}\leq \sum_{\zeta\in \Theta}  \langle x,x_{\zeta}\rangle_{\mathcal{A}} \langle x_{\zeta},x\rangle_{\mathcal{A}} \leq B \langle f,f\rangle_{\mathcal{A}},
	\end{equation}

\cite{Kh} A sequence $ \{\Psi_{\zeta} \in \operatorname{End}_{\mathcal{A}}^{\ast}(\mathcal{H},\mathcal{H}_{\zeta}): \zeta\in \Theta\} $ is said a $g-$frame for $ \mathcal{H} $ with respect to $ \{\mathcal{H}_{\zeta}: \zeta\in \Theta\} $. If there exist two positive constants $ A $ and $ B $ such that for $ x\in\mathcal{H} $,
	\begin{equation} \label{eq2}
			A\langle x,x\rangle_{\mathcal{A}}\leq \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}x,\Psi_{\zeta}x\rangle_{\mathcal{A}}  \leq B \langle x,x\rangle_{\mathcal{A}}.
	\end{equation}
The numbers $ A $ and $ B $ are called lower and upper  bounds of the $g-$frame, respectively. If $ A = B = \nu $, the $g-$frame is $ \nu- $tight. If $ A= B=1 $, it is called a $g$-Parseval frame. If olny the right-hand inequality (\ref{eq2}) is satisfied, the family  $ \{\Psi_{\zeta} \in \operatorname{End}_{\mathcal{A}}^{\ast}(\mathcal{H},\mathcal{H}_{\zeta}): \zeta\in \Theta\} $ is called a $g-$Bessel sequence for $\mathcal{H}$ with $g-$Bessel bound $B$.

Suppose $ \{\Psi_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $frame for  $ \mathcal{H} $, we have for some $ \alpha >0 $,
  	\begin{equation*}
  		  \alpha\langle x,x\rangle_{\mathcal{A}}\leq \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}x,\Psi_{\zeta}x\rangle_{\mathcal{A}},\: \forall x \in \mathcal{H}.  
  	\end{equation*} 
For any $x\in\mathcal{H}$, we have
	\begin{equation*}
\sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}x,\Psi_{\zeta}x\rangle_{\mathcal{A}}=\sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}^{\ast}\Psi_{\zeta}x,x\rangle_{\mathcal{A}}=\langle Sx,x\rangle_{\mathcal{A}}.  
\end{equation*} 

Therefore, $ \alpha I\leq S $.

  	Suppose $ \{\Psi_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence for $ \mathcal{H} $ and there exists some $ \alpha>0 $ such that $ S\geq \alpha I $. Thus, we have

  	$$ \langle  \alpha I x,x\rangle_{\mathcal{A}}\leq  \langle  S x,x\rangle_{\mathcal{A}}$$  for all $ x\in  \mathcal{H},$ this implies $$ \langle  \alpha I x,x\rangle_{\mathcal{A}}\leq \langle  \sum_{\zeta\in \Theta}\Psi_{\zeta}^{\ast}\Psi_{\zeta} x,x\rangle_{\mathcal{A}}.$$ 

  	Then, the lower condition holds:
  	\begin{equation*}
  		\alpha  \langle x,x\rangle_{\mathcal{A}} \leq  \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}x,\Psi_{\zeta}x\rangle_{\mathcal{A}},\; \forall x\in\mathcal{H}.
  	\end{equation*}

\label{L33}
  	Let $ \{\Psi_{\zeta} \in \operatorname{End}_{\mathcal{A}}^{\ast}(\mathcal{H},\mathcal{H}_{\zeta}): \zeta\in \Theta\} $ be a $g-$Bessel sequence for $\mathcal{H}$, with the
synthesis operator $\mathcal{T}$ and the $g-$frame operator $ S $. Then  $\mathcal{T}$ is surjective if only if $ S>0 $.

Assume that $ \{\Psi_{\zeta}\}_{\zeta\in \Theta} $ be a $ g- $frame and  $\Lambda \in \operatorname{End}_{\mathcal{A}}^{\ast}(\mathcal{H}) $ is bounded. 
	We have for any $ x\in\mathcal{H} $, 
	\begin{equation*}
			A\langle  x,x\rangle_{\mathcal{A}} \leq  \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}x,\Psi_{\zeta}x\rangle_{\mathcal{A}}\leq B\langle  x,x\rangle_{\mathcal{A}}
	\end{equation*}
	and 
	\begin{align*}
		   \langle( \Psi_{\zeta}+\Lambda \Psi_{\zeta})x,(\Psi_{\zeta}+\Lambda \Psi_{\zeta})x\rangle_{\mathcal{A}}
&=  \langle  \Psi_{\zeta}x,\Psi_{\zeta} x\rangle_{\mathcal{A}}+   \langle  \Psi_{\zeta}\Lambda x,\Psi_{\zeta}\Lambda x\rangle_{\mathcal{A}} +   \langle  \Psi_{\zeta}x,\Psi_{\zeta}\Lambda x\rangle_{\mathcal{A}} \\&+   \langle  \Psi_{\zeta}\Lambda x,\Psi_{\zeta} x\rangle_{\mathcal{A}}\\
&\leq 2 \left(\langle  \Psi_{\zeta}x,\Psi_{\zeta} x\rangle_{\mathcal{A}}+   \langle  \Psi_{\zeta}\Lambda x,\Psi_{\zeta}\Lambda x\rangle_{\mathcal{A}} \right)
	\end{align*}
Therefore	
	\begin{align*}
		  \sum_{\zeta\in \Theta}  \langle( \Psi_{\zeta}+\Lambda \Psi_{\zeta})x,(\Psi_{\zeta}+\Lambda \Psi_{\zeta})x\rangle_{\mathcal{A}}
&\leq 2\left( \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}x,\Psi_{\zeta} x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}\Lambda x,\Psi_{\zeta}\Lambda x\rangle_{\mathcal{A}}\right)\\
&\leq 2B(1+\Vert \Lambda \Vert^{2})\langle  x,x\rangle_{\mathcal{A}}.
	\end{align*}
Thus,  $ \{\Psi_{\zeta}+\Psi_{\zeta}\Lambda\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence. Since $ \{\Psi_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $frame for  $ \mathcal{H} $, by Proposition \ref{p1}, for some $ \alpha >0$, we have $ S\geq \alpha I $. Also, for every $ x\in \mathcal{H} $, we get 
\begin{align*}
	 \sum_{\zeta\in \Theta} (  \Psi_{\zeta}+\Lambda \Psi_{\zeta})^{\ast}(\Psi_{\zeta}+\Lambda \Psi_{\zeta})&=  \sum_{\zeta\in \Theta}  \left( \Psi_{\zeta}^{\ast}\Psi_{\zeta}+ \Psi_{\zeta}^{\ast}\Psi_{\zeta}\Lambda \right. +\left.  \Lambda^{\ast}\Psi_{\zeta}^{\ast}\Psi_{\zeta}+ \Lambda^{\ast}\Psi_{\zeta}^{\ast}\Psi_{\zeta}\Lambda \right) \\
	 & =  S+S\Lambda+\Lambda^{\ast}S+\Lambda^{\ast}S\Lambda\\
	 &=( I+\Lambda)^{\ast}S(I+\Lambda)
\end{align*} 
Then, 
$$ \mathcal{P}= S+S\Lambda+\Lambda^{\ast}S+\Lambda^{\ast}S\Lambda=( I+\Lambda)^{\ast}S(I+\Lambda)\geq S $$
 Hence the operator $\mathcal{P}$  is the $ g- $frame operator of $ \{\Psi_{\zeta}+\Psi_{\zeta}\Lambda\}_{\zeta\in \Theta} $. So, $ \mathcal{P}\geq \alpha I $ for some $ \alpha>0 $. Using proposition \ref{p1} we obtain $ \{\Psi_{\zeta}+\Psi_{\zeta}\Lambda\}_{\zeta\in \Theta} $ is a $ g- $frame for $ \mathcal{H} $ with respect to $ \{\mathcal{H}_{\zeta}\}_{\zeta\in \Theta} $.

\label{t3}
	Let $\Psi= \{\Psi_{\zeta}\}_{\zeta\in \Theta} $ and $ \Delta= \{\Delta_{\zeta}\}_{\zeta\in \Theta} $  are two $ g- $Bessel sequences for $ \mathcal{H} $ with the synthesis operators $ \mathcal{T}_{\Psi} $, $ \mathcal{T}_{\Delta} $ and the $ g- $frame operators $ S_{\Psi} $, $ S_{\Delta} $, respectively. If $ M $, $ N \in \operatorname{End}_{\mathcal{A}}^{\ast}(\mathcal{H}) $, then the following conditions are equivalents: 
	\begin{itemize}
		\item [(1)]  $ \{\Psi_{\zeta}M+\Delta_{\zeta}N\}_{\zeta\in \Theta} $ is a $ g- $frame for $ \mathcal{H} $.
		\item[(2)] $ M^{\ast}\mathcal{T}_{\Psi}+N\mathcal{T}_{\Delta} $ is surjective.
		\item[(3)] $ S= M^{\ast}S_{\Psi}M+M^{\ast}\mathcal{T}_{\Psi}\mathcal{T}^{\ast}_{\Delta}N+N^{\ast}\mathcal{T}_{\Delta}\mathcal{T}^{\ast}_{\Psi}M+N^{\ast}S_{\Delta}N>0 $.
	\end{itemize}
Then, $ S $ is the $ g- $frame operator of $ \{\Psi_{\zeta}M+\Delta_{\zeta}N\}_{\zeta\in \Theta} $.

Let $ D_{1} $, $ D_{2} $ be $ g- $Bessel bounds of $ \Psi $ and $ \Delta $, respectively. Since $ M, $ $ N $ are bounded, for any $ x\in \mathcal{H} $, we have 
	\begin{align*}
		  \sum_{\zeta\in \Theta}  \langle( \Psi_{\zeta}M+ \Delta_{\zeta}N)x,( \Psi_{\zeta}M+ \Delta_{\zeta}N)x\rangle_{\mathcal{A}}&\leq  2\left(\sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}Nx,\Delta_{\zeta}N x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}M x,\Psi_{\zeta}M x\rangle_{\mathcal{A}}\right)\\
		&\leq 2(D_{1} \Vert M \Vert^{2}+D_{2} \Vert N \Vert^{2})\langle x,x \rangle_{\mathcal{A}}.
	\end{align*} 
Then,  $ \{\Psi_{\zeta}M+\Delta_{\zeta}N\}_{\zeta\in \Theta} $ is a  $ g- $Bessel sequence for $ \mathcal{H} $. 

If $ \mathcal{T} $ is the synthesis operator of $ \{\Psi_{\zeta}M+\Delta_{\zeta}N\}_{\zeta\in \Theta} $, then we have 
\begin{equation*}
	\mathcal{T}^{\ast}x =  \{(\Psi_{\zeta}M+\Delta_{\zeta}N)x\}_{\zeta\in \Theta} =\mathcal{T}_{\Psi}^{\ast} M x+\mathcal{T}_{\Delta}^{\ast} N x,\;\forall x\in \mathcal{H}.
\end{equation*} 
i.e. $ \mathcal{T}= M^{\ast}\mathcal{T}_{\Psi} +N^{\ast}\mathcal{T}_{\Delta}   $.

 By Lemma \ref{L33}, the conditions $ (1) $ and $ (2) $ are equivalents. Moreover, we have 
 \begin{equation*}
 	S=\mathcal{T} \mathcal{T}^{\ast}= M^{\ast}S_{\Psi}M+M\mathcal{T}_{\Psi}\mathcal{T}^{\ast}_{\Delta}N+ N^{\ast}\mathcal{T}_{\Delta}\mathcal{T}^{\ast}_{\Psi}M+N^{\ast}S_{\Delta}N>0.
 \end{equation*}
Therefore, the conditions $ (2) $ and $ (3) $ are equivalent.

If $ M=N=I $ in Theorem \ref{t3}, then the $ g- $frame operator of the $ g- $Bessel sequence  $ \{\Psi_{\zeta}+\Delta_{\zeta}\}_{\zeta\in \Theta} $ is as follows:
	\begin{align*}
	    S&= \mathcal{T}_{\Psi}\mathcal{T}_{\Psi}^{\ast}+\mathcal{T}_{\Psi}\mathcal{T}^{\ast}_{\Delta}+\mathcal{T}_{\Delta}\mathcal{T}^{\ast}_{\Psi} \\
	   &= S_{\Psi}+\mathcal{T}_{\Psi}\mathcal{T}_{\Delta}^{\ast}+\mathcal{T}_{\Delta}\mathcal{T}_{\Psi}^{\ast}+S_{\Delta}>0.
	 \end{align*}

We have for any $ x\in\mathcal{H} $, 
 	\begin{align*}
 		 \sum_{\zeta\in \Theta}  \langle( \theta_{\zeta} \Psi_{\zeta}+ \delta_{\zeta} \Delta_{\zeta})x,(\theta_{\zeta} \Psi_{\zeta}+ \delta_{\zeta}\Delta_{\zeta})x\rangle_{\mathcal{A}}
  &\leq  2\left(\sum_{\zeta\in \Theta}  \langle  \delta_{\zeta}\Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta} \Psi_{\zeta} x\rangle_{\mathcal{A}}\right)\\
 		&\leq2 B( D_{\Delta}+D^{\prime})\langle x,x\rangle_{\mathcal{A}}.
 	\end{align*} 
And for every $ x\in\mathcal{H} $, we obtain 
 \begin{align*}
 \Vert \sum_{\zeta\in \Theta}  \langle( \theta_{\zeta} \Psi_{\zeta}+ \delta_{\zeta} \Delta_{\zeta})x,(\theta_{\zeta} \Psi_{\zeta}+ \delta_{\zeta}\Delta_{\zeta})x\rangle_{\mathcal{A}}\Vert^{\frac{1}{2}} &\geq \Vert \sum_{\zeta\in \Theta}  \langle  (\theta_{\zeta}\Psi_{\zeta})x,(\theta_{\zeta}\Psi_{\zeta}) x\rangle_{\mathcal{A}}\Vert^{\frac{1}{2}} \\ &-\Vert \sum_{\zeta\in \Theta}  \langle(  \delta_{\zeta} \Delta_{\zeta})x,( \delta_{\zeta}\Delta_{\zeta})x\rangle_{\mathcal{A}}\Vert^{\frac{1}{2}}\\
 	  	&\geq (\sqrt{AD}-\sqrt{BD_{\Delta}})\Vert x \Vert.
 	  \end{align*} 

Therefore $ \{ \theta_{\zeta}\Psi_{\zeta}+\delta_{\zeta}\Delta_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $frame for $ \mathcal{H} $ with respect to $\{ \mathcal{H}_{\zeta}\}_{\zeta\in \Theta} $.

Using the proof of Theorem \ref{t11}, for every $ x\in\mathcal{H}  $ we have 
 		\begin{align*}
 		 \sum_{\zeta\in \Theta}  \langle( \Psi_{\zeta}+  \Delta_{\zeta})x,( \Psi_{\zeta}+ \Delta_{\zeta})x\rangle_{\mathcal{A}} &	= ( \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}x, \Psi_{\zeta} x\rangle_{\mathcal{A}})\\ 
 		&=( \alpha_{1}+\alpha_{2})\langle x,x\rangle_{\mathcal{A}}.
 		\end{align*}
 		Where $  \sum\limits_{\zeta\in \Theta}  \langle  \Psi_{\zeta}x,\Psi_{\zeta} x\rangle_{\mathcal{A}}= \alpha_{1}\langle x,x\rangle_{\mathcal{A}} $ and $ \sum\limits_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}}= \alpha_{2}\langle x,x\rangle_{\mathcal{A}}. $

Similar to the proof of Theorem \ref{t3}, let $ A $ be a lower $ g- $frame bound of $ \Psi $ and $ \{(\Psi_{\zeta}+\Delta_{\zeta})\Lambda\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence for $ \mathcal{H} $ with respect to $ \{	\mathcal{H}_{\zeta}\}_{\zeta\in \Theta} $.
 For every $ x\in\mathcal{H} $, we have 
 	\begin{align*}
 		 \sum_{\zeta\in \Theta} \langle (\Psi_{\zeta}+\Delta_{\zeta})\Lambda,(\Psi_{\zeta}+\Delta_{\zeta})\Lambda \rangle_{{\mathcal{A}}}  &=   \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}\Lambda x,\Delta_{\zeta} \Lambda x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}\Lambda x, \Psi_{\zeta} \Lambda x\rangle_{\mathcal{A}}\\&+  \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}\Lambda x,\Delta_{\zeta}\Lambda x\rangle_{\mathcal{A}}+
 		 \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta} \Lambda x,\Psi_{\zeta} \Lambda x\rangle_{\mathcal{A}}\\
 		&=  \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}\Lambda x,\Delta_{\zeta}\Lambda x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}\Lambda x, \Psi_{\zeta} \Lambda x\rangle_{\mathcal{A}}\\
 		&+\langle \mathcal{T}_{\Psi}\mathcal{T}^{\ast}_{\Delta}\Lambda x,\Lambda x\rangle_{{\mathcal{A}}} +\langle \mathcal{T}_{\Delta}\mathcal{T}^{\ast}_{\Psi}\Lambda x,\Lambda x\rangle_{{\mathcal{A}}} .
 	\end{align*}
 So, 

 \begin{equation*}
 		 \sum_{\zeta\in \Theta} \langle (\Psi_{\zeta}+\Delta_{\zeta})\Lambda,(\Psi_{\zeta}+\Delta_{\zeta})\Lambda \rangle_{{\mathcal{A}}}  \geq  \sum_{\zeta\in \Theta}  \langle  \Psi_{\zeta}\Lambda x, \Psi_{\zeta} \Lambda x\rangle_{\mathcal{A}} \geq A \Vert \Lambda x \Vert^{2} =A\langle x,x\rangle_{\mathcal{A}},
 \end{equation*}

Similar to the proof of Theorem \ref{t3}, $ \{(\Psi_{\zeta}+\Delta_{\zeta})M\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence for $ \mathcal{H} $ with respect to $ \{	\mathcal{H}_{\zeta}\}_{\zeta\in \Theta} $. For any $ x\in\mathcal{H} $, we obtain 
	\begin{align*}
	\Vert \sum_{\zeta\in \Theta} \langle (\Psi_{\zeta}+\Delta_{\zeta})M,(\Psi_{\zeta}+\Delta_{\zeta})M \rangle_{{\mathcal{A}}} \Vert^{\frac{1}{2}}  &\geq   \Vert\sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}M x, \Psi_{\zeta} Mx\rangle_{\mathcal{A}}\Vert^{\frac{1}{2}}  - \Vert\sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}Nx,\Delta_{\zeta} N x\rangle_{\mathcal{A}}\Vert^{\frac{1}{2}}  \\&\geq  \sqrt{D}  \Vert   M x\Vert -\sqrt{D_{\Delta}} 
	\Vert N x\Vert \\
	&\geq (\sqrt{D}-\sqrt{D_{\Delta}})\Vert Nx \Vert  \\
 &\geq \lambda(\sqrt{D}-\sqrt{D_{\Delta}})\Vert x \Vert  .
\end{align*}
Therefore, $ \lambda^{2}(\sqrt{D}-\sqrt{D_{\Delta}})^{2} $ is a lower $ g- $frame bound for $ \{(\Psi_{\zeta}+\Delta_{\zeta})M\}_{\zeta\in \Theta} $.

According to the proof of Theorem \ref{t3} $ \{(\Psi_{\zeta}+\Delta_{\zeta})M\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence for $ \mathcal{H} $. Since $ \mathcal{T}_{\Psi}\mathcal{T}^{\ast}_{\Delta}=0$, for any $ x\in\mathcal{H} $, we get $ \sum_{\zeta\in \Theta}  \Psi_{\zeta}^{\ast}\Delta_{\zeta}x =0$.


For every $ x\in \mathcal{H}$, we have
	\begin{equation*}
		\sum_{\zeta\in \Theta} \langle \Psi_{\zeta}M x, \Delta_{\zeta}Nx\rangle_{{\mathcal{A}}} = \sum_{\zeta\in \Theta} \langle M x,\Psi_{\zeta}^{\ast} \Delta_{\zeta}Nx\rangle_{{\mathcal{A}}} =\langle M x,\sum_{\zeta\in \Theta}  \Psi_{\zeta}^{\ast}\Delta_{\zeta}Nx\rangle_{{\mathcal{A}}}= 0.
	\end{equation*}

	We obtain, 
	\begin{align*}
	 \sum_{\zeta\in \Theta} \langle (\Psi_{\zeta}M+\Delta_{\zeta}N)x,(\Psi_{\zeta}M+\Delta_{\zeta}N)x \rangle_{{\mathcal{A}}}  &=   \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}Nx,\Delta_{\zeta} N x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}M x, \Psi_{\zeta} M x\rangle_{{\mathcal{A}}}
\end{align*}
Then, we get
\begin{align*}
	   \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}Nx,\Delta_{\zeta} N x\rangle_{\mathcal{A}}+ \sum_{\zeta\in \Theta}  \langle \Psi_{\zeta}M x, \Psi_{\zeta} M x\rangle_{{\mathcal{A}}}& = \alpha_{1}\Vert M x\Vert ^{2}+ \alpha_{2} \Vert Nx \Vert^{2} \\
	  &= \langle \alpha_{1}M^{*}M x,x\rangle_{{\mathcal{A}}}+ \langle \alpha_{2}N^{*}Nx,x\rangle_{{\mathcal{A}}}\\
	&= \langle \alpha_{1}M^{*}M x+\alpha_{2} N^{*}Nx,x\rangle_{{\mathcal{A}}}\\
		&= \langle \alpha Ix,x\rangle_{{\mathcal{A}}}\\
			&= \alpha  \langle x,x\rangle_{{\mathcal{A}}}.
\end{align*}

For any $ x\in\mathcal{H} $, 
	\begin{align*}
		\left(\Vert \sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta}\Psi_{\zeta} x\rangle_{\mathcal{A}}\Vert\right)^{\frac{1}{2}} &\leq \left( \Vert \sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta}\Psi_{\zeta} x\rangle_{\mathcal{A}} \Vert - \Vert \sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\Vert \right)^{\frac{1}{2}}\\
		&+\left(\Vert\sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\Vert\right)^{\frac{1}{2}}\\
		&\leq \alpha_{1} \left( \Vert\sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta}\Psi_{\zeta} x\rangle_{\mathcal{A}}\Vert\right)^{\frac{1}{2}}	+\alpha_{2}\left(\Vert\sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\Vert\right)^{\frac{1}{2}}\\
		&+\left(\Vert\sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\Vert\right)^{\frac{1}{2}}.
	\end{align*}
	Then, we obtain 
	\begin{equation*}
		\left(1-\alpha_{1}\right)	\left( \sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta}\Psi_{\zeta} x\rangle_{\mathcal{A}}\right)^{\frac{1}{2}}\leq \left(1+\alpha_{2}\right)\left(\sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\right)^{\frac{1}{2}}.
	\end{equation*}
So, we have
\begin{equation*}
	CA\left(1-\alpha_{1}\right)^{2} \langle x, x\rangle_{\mathcal{A}}\leq B \left(1+\alpha_{2}\right)^{2}\left(\sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}}\right).
\end{equation*} 
This implies that $  \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}} \geq \dfrac{CA\left(1-\alpha_{1}\right)^{2}}{ B \left(1+\alpha_{2}\right)^{2}}\langle x, x\rangle_{\mathcal{A}} $, $ \forall x\in\mathcal{H} $.

On the other hand, for any $ x\in\mathcal{H} $ we get 
	\begin{equation*}
	\left(1-\alpha_{2}\right)	\left( \sum_{\zeta\in \Theta}  \langle \delta_{\zeta}\Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}}\right)^{\frac{1}{2}}\leq \left(1+\alpha_{1}\right)\left(\sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\ \theta_{\zeta} \Psi_{\zeta}x\rangle_{\mathcal{A}}\right)^{\frac{1}{2}}.
\end{equation*}
So, we obtain 
\begin{equation*}
	A\left(1-\alpha_{2}\right)^{2}\left(\sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}}\right)\leq \langle x, x\rangle_{\mathcal{A}} DB \left(1+\alpha_{2}\right)^{2}.
\end{equation*}
Therefore,   $ \sum_{\zeta\in \Theta}  \langle  \Delta_{\zeta}x,\Delta_{\zeta} x\rangle_{\mathcal{A}}\leq \dfrac{BD \left(1+\alpha_{2}\right)^{2}}{A\left(1-\alpha_{1}\right)^{2} } \langle x, x\rangle_{\mathcal{A}}$, $ \forall x\in\mathcal{H} $.

Let $ \Psi= \{\Psi_{\zeta}\} _{\zeta\in \Theta}$
	be a $ g- $frame for $ \mathcal{H} $ with bounds $ C $, $ D $ and $  \Delta= \{\Delta_{\zeta}\}_{\zeta\in \Theta} $. Let    $ \{\theta_{\zeta}\}_{\zeta\in \Theta} $ and $ \{\delta_{\zeta}\}_{\zeta\in \Theta} $ are two sequences from the algebra $\mathcal{A}$ such that $ 0< A< \theta_{\zeta}^{2} ,  \delta_{\zeta}^{2}<B< \infty$ and $ 0< \alpha_{1},\alpha_{2}<1 $ such that for any $ x\in \mathcal{H} $,
	\begin{equation*}
\sum_{\zeta\in \Theta}  \langle (\theta_{\zeta} \Psi_{\zeta}-\delta_{\zeta} \Delta_{\zeta})x,(\theta_{\zeta}\Psi_{\zeta}-\delta_{\zeta} \Delta_{\zeta}) x\rangle_{\mathcal{A}}\leq \alpha_{1} (  \sum_{\zeta\in \Theta}  \langle \theta_{\zeta} \Psi_{\zeta}x,\theta_{\zeta}\Psi_{\zeta} x\rangle_{\mathcal{A}})	+\alpha_{2}( \sum_{\zeta\in \Theta}  \langle \delta_{\zeta} \Delta_{\zeta}x,\delta_{\zeta}\Delta_{\zeta} x\rangle_{\mathcal{A}})
	\end{equation*}

	then  $\{ \Delta_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $frame for $ \mathcal{H} $ with respect to $ \{	\mathcal{H}_{\zeta\in \Theta}\}_{\zeta\in \Theta} $.

\label{t12}Let $ \Psi= \{\Psi_{\zeta}\} _{\zeta\in \Theta}$
be a $ g- $frame for $ \mathcal{H} $ with bounds $ C $, $ D $ $ (D>1) $ and assume that $  \Delta= \{\Delta_{\zeta}\}_{\zeta\in \Theta} $ is a family so that for any $ J\subset \Theta $ with $ \vert J\vert< \infty  $, we have 
\begin{equation*}
	\Vert \sum_{\zeta\in J}( \Psi_{\zeta}^{*}\Psi_{\zeta}-\Delta_{\zeta})x \Vert \leq \dfrac{C}{D}\Vert x\Vert, \;\forall x\in\mathcal{H}. 
\end{equation*}
	Then  $\{ \Delta_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $frame for $ \mathcal{H} $ with bounds $ \dfrac{1}{C}(\dfrac{D+1}{D} )$, $ \dfrac{C+D^{2}}{D} $.

For any $ x\in\mathcal{H} $ we have

	\begin{align*}
		\Vert \sum_{\zeta\in J} \Psi_{\zeta}^{*}\Psi_{\zeta}x\Vert& = \sup_{y\in\mathcal{H}, \Vert y\Vert =1}\Vert \langle \sum_{\zeta\in J} \Psi_{\zeta}^{*}\Psi_{\zeta}x, y\rangle_{\mathcal{A}} \Vert\\
		&= \sup_{y\in\mathcal{H}, \Vert y\Vert =1}\Vert  \sum_{\zeta\in J}\langle \Psi_{\zeta}x, \Psi_{\zeta}y\rangle_{\mathcal{A}} \Vert\\
		&\leq \sup_{y\in\mathcal{H}, \Vert y\Vert =1}\Vert  \sum_{\zeta\in J}\langle \Psi_{\zeta}x, \Psi_{\zeta}x \rangle_{\mathcal{A}} \Vert^{\frac{1}{2}} \Vert  \sum_{\zeta\in J}\langle \Psi_{\zeta}y, \Psi_{\zeta}y\rangle_{\mathcal{A}} \Vert^{\frac{1}{2}}\\
		&\leq \sqrt{D} \Vert  \sum_{\zeta\in J}\langle \Psi_{\zeta}x, \Psi_{\zeta}x\rangle_{\mathcal{A}} \Vert^{\frac{1}{2}}\\
		&\leq D \Vert x\Vert .
	\end{align*}
So we obtain 

\begin{equation*}
		\Vert \sum_{\zeta\in J} \Delta_{\zeta}^{*}\Delta_{\zeta}x\Vert\leq (\dfrac{C}{D}+D) \Vert x\Vert. 
\end{equation*}
Hence, the series $ \sum_{\zeta\in \Theta}\Delta_{\zeta}^{*}\Delta_{\zeta}x $ converge. We define 
\begin{equation*}
	\mathcal{K}(x)= \sum_{\zeta\in \Theta} \Delta_{\zeta}^{*}\Delta_{\zeta}x ,\;\forall x\in\mathcal{H}.
	\end{equation*}
This operator is well defined and bounded on $ \mathcal{H} $ and $ \Vert \mathcal{K}  \Vert\leq   \dfrac{C}{D}+D$. 

Also for $ x\in\mathcal{H} $
\begin{align*}
		\Vert \sum_{\zeta\in \Theta} \Delta_{\zeta}x\Vert^{2} &= \Vert \sum_{\zeta\in \Theta}\langle \Delta_{\zeta}x,\Delta_{\zeta}x\rangle_{\mathcal{A}}\Vert\\
		&\leq \Vert \mathcal{K} \Vert \Vert x\Vert ^{2}.
\end{align*}
That is $ \{\Delta_{\zeta}\}_{\zeta\in \Theta} $ is a $ g- $Bessel sequence for $ \mathcal{H} $. If $ S $ is the $ g- $frame operator of $ \{\Psi_{\zeta}\}_{\zeta\in \Theta} $, we get for all $ x\in\mathcal{H} $ $$ \Vert Sx-\mathcal{K} x\Vert \leq \dfrac{C}{D} \Vert x\Vert.$$ 
Then, $ \Vert x- \mathcal{K} S^{-1}x \Vert \leq \dfrac{1}{D}\Vert x\Vert \Rightarrow  \Vert I- \mathcal{K} S^{-1} \Vert \leq \dfrac{1}{D}\leq 1$.
Hence, $ \mathcal{K} S^{-1} $ is invertible and so is $ \mathcal{K}  $. Therefore, $ \{\Delta_{\zeta}\}_{\zeta} $ is a $ g- $frame for $ \mathcal{H} $. Also, we have for $ x\in\mathcal{H} $
 \begin{equation*}
 \Vert	\mathcal{K} ^{-1}\Vert \leq \Vert S^{-1}\Vert \Vert S\mathcal{K} ^{-1}\Vert \leq \dfrac{1}{C}(\dfrac{D+1}{D}).
 \end{equation*}
Therefore, $ \dfrac{1}{C}(\dfrac{D+1}{D}) $, $ \dfrac{C}{A}+D $ are bounds for $ \{\Delta_{\zeta}\}_{\zeta} $.
